package got.client.wildlife;
import net.minecraft.client.model.HierarchicalModel; import net.minecraft.client.model.geom.*; import net.minecraft.client.model.geom.builders.*; import net.minecraft.util.Mth; import net.minecraft.world.entity.LivingEntity;
public final class GOTScorpionModel<T extends LivingEntity> extends HierarchicalModel<T>{private final ModelPart root,body; public GOTScorpionModel(ModelPart r){root=r;body=r.getChild("body");} public static LayerDefinition layer(){MeshDefinition m=new MeshDefinition();PartDefinition r=m.getRoot();PartDefinition b=r.addOrReplaceChild("body",CubeListBuilder.create().texOffs(0,0).addBox(-4,-2,-5,8,4,10),PartPose.offset(0,20,0));b.addOrReplaceChild("tail",CubeListBuilder.create().texOffs(0,15).addBox(-1,-1,0,2,2,11),PartPose.offsetAndRotation(0,-1,5,-.75F,0,0));for(int i=0;i<4;i++){float z=-3+i*2;b.addOrReplaceChild("legL"+i,CubeListBuilder.create().texOffs(28,0).addBox(0,-.5F,-.5F,7,1,1),PartPose.offsetAndRotation(3,0,z,0,.35F,0));b.addOrReplaceChild("legR"+i,CubeListBuilder.create().texOffs(28,0).addBox(-7,-.5F,-.5F,7,1,1),PartPose.offsetAndRotation(-3,0,z,0,-.35F,0));}b.addOrReplaceChild("clawL",CubeListBuilder.create().texOffs(28,8).addBox(0,-1,-1,7,2,2),PartPose.offsetAndRotation(3,0,-4,0,-.35F,0));b.addOrReplaceChild("clawR",CubeListBuilder.create().texOffs(28,8).addBox(-7,-1,-1,7,2,2),PartPose.offsetAndRotation(-3,0,-4,0,.35F,0));return LayerDefinition.create(m,64,32);} public ModelPart root(){return root;} public void setupAnim(T e,float s,float a,float age,float yaw,float pitch){body.yRot=Mth.sin(age*.08F)*.03F;}}
